  const p = x.getImageData(0, 0, w, h); for (let y = 0; y < h; y++) for (let xx = 0; xx < w; xx++) { const k = (y * w + xx) * 4, shadow = .96 - .32 * Math.exp(-1 * ((xx - w * .73) / (w * .4)) ** 2) * (.25 + .75 * y / h), fold = 1 - .10 * Math.exp(-1 * ((xx - w * .48 - y * .016) / 13) ** 2) + .03 * Math.exp(-1 * ((xx - w * .48 - 17 - y * .016) / 10) ** 2); for (let ch = 0; ch < 3; ch++) p.data[k + ch] *= shadow * fold * [1, .99, .98][ch]; } x.putImageData(p, 0, 0); return c;
